<?php require_once __DIR__.'/../funciones.php'; exigir_admin();$clientes=(int)$conn->query("SELECT COUNT(*) c FROM usuarios WHERE rol='cliente'")->fetch_assoc()['c'];$productos=(int)$conn->query('SELECT COUNT(*) c FROM productos')->fetch_assoc()['c'];$pedidos=(int)$conn->query("SELECT COUNT(*) c FROM pedidos WHERE estado='Pendiente'")->fetch_assoc()['c'];$ventas=(float)$conn->query("SELECT COALESCE(SUM(total),0) t FROM pedidos WHERE estado<>'Cancelado'")->fetch_assoc()['t'];?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Administración</title><link rel="stylesheet" href="../estilos.css"></head><body><?php include 'menu.php';?><main class="contenedor"><h1 class="titulo">Resumen general</h1><p class="muted">Desde aquí puedes controlar tu restaurante.</p><?php mostrar_aviso();?><div class="stats"><div class="stat">Clientes registrados<strong><?=$clientes?></strong></div><div class="stat">Productos<strong><?=$productos?></strong></div><div class="stat">Pedidos pendientes<strong><?=$pedidos?></strong></div><div class="stat">Ventas no canceladas<strong>S/ <?=number_format($ventas,2)?></strong></div></div><div class="panel"><h2 class="titulo">Administración de Como en Casa</h2><p>Usa el menú superior para agregar, editar o eliminar productos, revisar clientes, gestionar pedidos y configurar métodos de pago y envío.</p><div class="acciones"><a class="btn" href="productos.php">Administrar productos</a><a class="btn btn-vino" href="pedidos.php">Revisar pedidos</a></div></div></main></body></html>
